
/**
 * MangaKatana client — the site's primary manhwa/manhua content source.
 *
 * mangakatana.com is a plain SSR HTML site with no JSON API, so the catalog
 * comes from the prebuilt snapshot (public/catalog-mk.json, generated by
 * scripts/fetch-mangakatana.mjs) and only the per-chapter page manifests are
 * fetched live — through the same-origin edge proxy at /api/mk, which
 * extracts the image URLs embedded in each chapter page's HTML.
 *
 * FALLBACK SOURCES: MangaKatana has full-outage windows (site-wide 504s)
 * and IP soft-throttling — since 2026-09-22 it also serves degraded
 * placeholder markup to datacenter clients (Cloudflare egress), so the
 * newest chapters of busy titles can be unfetchable for days. When the mk
 * page fetch fails or returns no pages, the same title is resolved on
 * mgeko.cc (/api/mg), then weebcentral.com (/api/wc — the MangaSee
 * successor, added §29: plain SSR, no challenge, hotlink-friendly image
 * host), then asurascans.com (/api/as) and its chapter pages are used
 * instead — the user sees pages rather than a dead reader. Resolution is
 * cached per series; per-chapter page manifests are cached like the
 * primary ones.
 *
 * Chapter image URLs are served DIRECT from the source CDNs (the reader
 * swaps to /api/md?img=… automatically if a direct load fails) — each
 * page view would otherwise be a Function invocation, and the account's
 * daily invocation budget is the binding constraint. The proxy allowlist
 * still covers every source CDN, so this stays a one-line change.
 */

const API = '/api/mk'
const MG_API = '/api/mg'
const WC_API = '/api/wc'
const AS_API = '/api/as'
const PAGES_KEY = 'manhwas:mk:pages:v1' // chapter path → { at, pages }
const FB_PAGES_KEY = 'manhwas:fb:pages:v1' // fallback chapter (api+path) → { at, pages }
const MG_SERIES_KEY = 'manhwas:mg:series:v1' // mk series slug → mgeko chapters
const WC_SERIES_KEY = 'manhwas:wc:series:v1' // mk series slug → weebcentral chapters
const AS_SERIES_KEY = 'manhwas:as:series:v1' // mk series slug → asura chapters
const TTL = 24 * 60 * 60 * 1000 // 24h — page manifests are immutable
const SERIES_TTL = 6 * 60 * 60 * 1000 // 6h — fallback chapter lists change slowly
const MAX_CACHED_CHAPTERS = 100 // bound localStorage growth

function lsGet<T>(key: string): T | null {
  try {
    const raw = localStorage.getItem(key)
    return raw ? (JSON.parse(raw) as T) : null
  } catch {
    return null
  }
}

function lsSet(key: string, value: unknown): void {
  try {
    localStorage.setItem(key, JSON.stringify(value))
  } catch {
    /* storage full — non-fatal */
  }
}

/** True when the series' chapters come from the MangaKatana snapshot. */
export function isMangaKatanaSeries(series: { slug: string }): boolean {
  return series.slug.startsWith('mk-')
}

async function fetchJson<T>(url: string, source: string): Promise<T> {
  const res = await fetch(url, { headers: { Accept: 'application/json' } })
  if (!res.ok) throw new Error(`${source} ${res.status}`)
  return (await res.json()) as T
}

/**
 * Manifest archive on the public CDN (cdn.manhwas.site). Every successful
 * manifest extraction is mirrored there by the edge functions; reading from
 * the archive costs NO Function invocation (the daily budget's binding
 * constraint) and keeps working when the functions themselves are down
 * (budget exhausted, deployment incident). Key prefixes per source:
 * mk-pages/ (mangakatana), mg-pages/ (mgeko), as-pages/ (asurascans).
 */
const CDN_ORIGIN = 'https://cdn.manhwas.site'

async function fetchArchivedPages(prefix: string, path: string): Promise<string[]> {
  try {
    const key = `${prefix}/${path.replace(/^\//, '').replace(/\/$/, '')}.json`
    const d = await fetchJson<{ pages?: string[] }>(`${CDN_ORIGIN}/${key}`, 'archive')
    return d.pages ?? []
  } catch {
    return []
  }
}

/* ------------------------------------------------------------------ *
 * Primary source: MangaKatana                                        *
 * ------------------------------------------------------------------ */

/**
 * Fetch the real page image URLs for a MangaKatana chapter
 * (e.g. '/manga/solo-leveling.24339/c1').
 *
 * Order: CDN archive → /api/mk. The archive first is deliberate — it is
 * free (no Function invocation) and survives function outages; the API is
 * only needed the first time any reader opens a given chapter.
 *
 * Image URLs are returned DIRECT (i1.mangakatana.com/token/…): the CDN
 * serves them without referer checks, and the reader drops back to the
 * /api/md?img= proxy automatically if a direct load fails (see the Reader's
 * onError handler). Proxying every page would cost ~40 Function invocations
 * per chapter read against the daily budget — this keeps the steady-state
 * cost at one manifest call per chapter.
 */
export async function fetchMangaKatanaPages(chapterPath: string): Promise<string[]> {
  const cache = lsGet<Record<string, { at: number; pages: string[] }>>(PAGES_KEY) ?? {}
  const hit = cache[chapterPath]
  if (hit && Date.now() - hit.at < TTL && hit.pages.length) return hit.pages

  let pages = await fetchArchivedPages('mk-pages', chapterPath)
  if (!pages.length) {
    // "ch", not "path": the vercel.json rewrite injects its own "path" query
    // param, which clobbers a same-named param of ours in production
    const d = await fetchJson<{ pages?: string[] }>(
      `${API}/pages?ch=${encodeURIComponent(chapterPath)}`,
      'MangaKatana',
    )
    pages = d.pages ?? []
  }
  if (pages.length) {
    cache[chapterPath] = { at: Date.now(), pages }
    const keys = Object.keys(cache)
    if (keys.length > MAX_CACHED_CHAPTERS) {
      for (const k of keys
        .sort((a, b) => cache[a].at - cache[b].at)
        .slice(0, keys.length - MAX_CACHED_CHAPTERS)) {
        delete cache[k]
      }
    }
    lsSet(PAGES_KEY, cache)
  }
  return pages
}

/* ------------------------------------------------------------------ *
 * Fallback sources: mgeko.cc (secondary), asurascans.com (tertiary)  *
 * ------------------------------------------------------------------ */

/**
 * Fetch readable pages for a MangaKatana-sourced chapter with a fallback
 * chain: primary /api/mk fetch first; when it fails or yields zero pages
 * (MangaKatana outage/throttle window), resolve the series on mgeko and
 * then asurascans and read the same chapter number there. Returns [] only
 * when every source has nothing — the reader then shows its
 * not-available notice.
 */
export async function fetchChapterPagesWithFallback(
  chapterPath: string,
  chapterNumber: number,
  seriesSlug: string,
  titles: string[],
): Promise<string[]> {
  let primary: string[] = []
  try {
    primary = await fetchMangaKatanaPages(chapterPath)
  } catch {
    /* primary down — fall through to the fallback chain */
  }
  if (primary.length) return primary

  // §29: the archive warmer backfills MK-warm failures on weebcentral and
  // stores them under the MK chapter path (wc-pages/manga/<slug>.<id>/cN.json).
  // This free CDN probe short-circuits the whole fallback resolution when it
  // hits — no function invocations, no upstream requests at all.
  const warmed = await fetchArchivedPages('wc-pages', chapterPath)
  if (warmed.length) return warmed

  for (const fallback of [mgekoChapter, weebcentralChapter, asuraChapter]) {
    try {
      const match = await fallback(seriesSlug, chapterNumber, titles)
      if (!match) continue
      const pages = await fetchFallbackPages(match.api, match.path)
      if (pages.length) return pages
    } catch {
      /* try the next source */
    }
  }
  return []
}

/* ------------------------------------------------------------------ *
 * Fallback source plumbing (mgeko + asurascans share the shape)      *
 * ------------------------------------------------------------------ */

interface FallbackChapter {
  api: string // proxy base ('/api/mg' | '/api/as')
  path: string // source-local chapter path
}

/** Search a title on a fallback source and return its series path. */
async function resolveSeries(
  api: string,
  titles: string[],
): Promise<string | null> {
  for (const t of titles) {
    try {
      const d = await fetchJson<{ results?: { path: string; title: string }[] }>(
        `${api}/?search=${encodeURIComponent(t)}`,
        'fallback',
      )
      const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '')
      const want = norm(t)
      const hit = d.results?.find(
        (r) =>
          norm(r.title) === want || norm(r.title).includes(want) || want.includes(norm(r.title)),
      )
      if (hit) return hit.path
    } catch {
      /* try the next title variant */
    }
  }
  return null
}

/** Generic fallback-chapter-list fetch with a per-source series cache. */
async function fallbackChapters(
  api: string,
  cacheKey: string,
  seriesSlug: string,
  titles: string[],
): Promise<{ path: string; number: number }[] | null> {
  const cache =
    lsGet<Record<string, { at: number; chapters: { path: string; number: number }[] }>>(cacheKey) ??
    {}
  const hit = cache[seriesSlug]
  if (hit && Date.now() - hit.at < SERIES_TTL && hit.chapters.length) return hit.chapters

  const seriesPath = await resolveSeries(api, titles)
  if (!seriesPath) return null
  const d = await fetchJson<{ chapters?: { path: string; number: number }[] }>(
    `${api}/?chapters=${encodeURIComponent(seriesPath)}`,
    'fallback',
  )
  const chapters = d.chapters ?? []
  if (!chapters.length) return null
  cache[seriesSlug] = { at: Date.now(), chapters }
  lsSet(cacheKey, cache)
  return chapters
}

/** Fetch the page image URLs of a fallback-source chapter, cached.
 *
 * Fallback images are served DIRECTLY from the source CDNs (imgsrv*.com,
 * cdn.asurascans.com) — both hotlink without referer checks, and proxying a
 * ~40-page chapter costs ~40 of the account's 100k daily function requests.
 * The proxy is reserved for sources that need it (mangadex: IP rate limits;
 * mangakatana: token URLs). If a fallback source ever starts blocking
 * hotlinks, route these through proxyImageUrl again (the /api/md allowlist
 * already covers both hosts). */
async function fetchFallbackPages(api: string, chapterPath: string): Promise<string[]> {
  const cache = lsGet<Record<string, { at: number; pages: string[] }>>(FB_PAGES_KEY) ?? {}
  // key the cache by source api + path so mgeko/asura entries never collide
  const key = api + chapterPath
  const hit = cache[key]
  if (hit && Date.now() - hit.at < TTL && hit.pages.length) return hit.pages

  // archive first (free, survives function outages), then the live proxy
  const prefix = api === '/api/mg' ? 'mg-pages' : api === '/api/wc' ? 'wc-pages' : 'as-pages'
  let pages = await fetchArchivedPages(prefix, chapterPath)
  if (!pages.length) {
    const d = await fetchJson<{ pages?: string[] }>(
      `${api}/?pages=${encodeURIComponent(chapterPath)}`,
      'fallback',
    )
    pages = d.pages ?? []
  }
  if (pages.length) {
    cache[key] = { at: Date.now(), pages }
    const keys = Object.keys(cache)
    if (keys.length > MAX_CACHED_CHAPTERS) {
      for (const k of keys
        .sort((a, b) => cache[a].at - cache[b].at)
        .slice(0, keys.length - MAX_CACHED_CHAPTERS)) {
        delete cache[k]
      }
    }
    lsSet(FB_PAGES_KEY, cache)
  }
  return pages
}

/** mgeko chapter lookup for an mk series + chapter number. */
async function mgekoChapter(
  seriesSlug: string,
  chapterNumber: number,
  titles: string[],
): Promise<FallbackChapter | null> {
  const chapters = await fallbackChapters(MG_API, MG_SERIES_KEY, seriesSlug, titles)
  return pickChapter(chapters, chapterNumber, MG_API)
}

/** weebcentral chapter lookup for an mk series + chapter number (§29).
 * weebcentral paths are ULID-keyed (/series/<ULID>, /chapters/<ULID>) —
 * opaque but stable, so they cache exactly like the mgeko/asura ones. */
async function weebcentralChapter(
  seriesSlug: string,
  chapterNumber: number,
  titles: string[],
): Promise<FallbackChapter | null> {
  const chapters = await fallbackChapters(WC_API, WC_SERIES_KEY, seriesSlug, titles)
  return pickChapter(chapters, chapterNumber, WC_API)
}

/** asurascans chapter lookup for an mk series + chapter number. */
async function asuraChapter(
  seriesSlug: string,
  chapterNumber: number,
  titles: string[],
): Promise<FallbackChapter | null> {
  const chapters = await fallbackChapters(AS_API, AS_SERIES_KEY, seriesSlug, titles)
  return pickChapter(chapters, chapterNumber, AS_API)
}

/** Exact number first (5.5 half-chapters), else nearest lower chapter. */
function pickChapter(
  chapters: { path: string; number: number }[] | null,
  chapterNumber: number,
  api: string,
): FallbackChapter | null {
  if (!chapters) return null
  const match =
    chapters.find((c) => c.number === chapterNumber) ??
    [...chapters].reverse().find((c) => c.number <= chapterNumber)
  return match ? { api, path: match.path } : null
}
