import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  ArrowLeft, ChevronLeft, ChevronRight, Star, X, Sun, Moon, ArrowUp, Home as HomeIcon,
  AlignCenterHorizontal, Maximize2, Minimize2, Settings2, Bookmark, ImageOff,
} from 'lucide-react'
import { useCatalog, useSeries } from '../lib/catalog-context'
import { useRealChapters, fetchChapterImages, proxyImageUrl } from '../lib/mangadex'
import { fetchChapterPagesWithFallback } from '../lib/mangakatana'
import { navigate } from '../lib/router'
import { setSeo, buildChapterMeta } from '../lib/seo'
import { useStore } from '../lib/store'
import { formatDate, formatViews, cx, clamp, seriesHref, chapterHref, titleSlug } from '../lib/utils'
import { StarRating, Button } from '../components/ui'
import Comments from '../components/Comments'
import BannerAd from '../components/BannerAd'
import { seededRandom } from '../lib/utils'
import posthog, { isPostHogEnabled } from '../lib/posthog'

const WIDTHS = [
  { key: 'narrow', label: 'Narrow', cls: 'max-w-[560px]' },
  { key: 'standard', label: 'Standard', cls: 'max-w-[760px]' },
  { key: 'wide', label: 'Wide', cls: 'max-w-[960px]' },
  { key: 'full', label: 'Full', cls: 'max-w-none' },
] as const

export default function Reader({ slug, chapterNumber }: { slug: string; chapterNumber: number }) {
  const { series: catalog } = useCatalog()
  const { series, loading } = useSeries(slug)
  // §30: the hook unions the MD feed window with the MK twin's ground truth
  // (mkTwinSlug stamped by title collapse) — newest chapters never blank out.
  const { chapters: realChapters, loading: realLoading } = useRealChapters(series)
  const { prefs, setAtmosphere, setWidth, rateChapter, ratings, setProgress, inLibrary, toggleLibrary, toast } = useStore()
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [fullscreen, setFullscreen] = useState(false)
  const [scrollPct, setScrollPct] = useState(0)
  const [pageImages, setPageImages] = useState<string[]>([])
  const [imagesLoading, setImagesLoading] = useState(false)
  const topRef = useRef<HTMLDivElement>(null)

  // Prefer the real MangaDex chapter list when this title is readable there —
  // but UNION it with the catalog list by chapter number. A lagging source
  // (MangaDex feed behind MangaKatana's newest uploads) must never blank a
  // chapter URL the catalog already serves — that was the "Chapter Not
  // Found" on brand-new chapters (§29). Catalog chapters only fill gaps;
  // MD wins on conflicts (it carries mdChapterId for page loading).
  const chapterSource = useMemo(() => {
    if (!realChapters) return series?.chapters ?? []
    const byNumber = new Map(realChapters.map((c) => [c.number, c]))
    for (const c of series?.chapters ?? []) {
      if (!byNumber.has(c.number)) byNumber.set(c.number, c)
    }
    return [...byNumber.values()].sort((a, b) => a.number - b.number)
  }, [realChapters, series])

  const chapter = useMemo(
    () => chapterSource.find((c) => c.number === chapterNumber),
    [chapterSource, chapterNumber],
  )

  // Fetch the real page images when the chapter has a readable source:
  // MangaDex chapters via the @Home manifest, MangaKatana chapters via the
  // /api/mk page extractor — with the mgeko.cc fallback when MangaKatana
  // has nothing (outage/throttle window)
  useEffect(() => {
    const mdId = chapter?.mdChapterId
    const mkPath = chapter?.chapterPath
    if (!mdId && !mkPath) {
      setPageImages([])
      setImagesLoading(false)
      return
    }
    let cancelled = false
    setImagesLoading(true)
    const load = mdId
      ? fetchChapterImages(mdId)
      : fetchChapterPagesWithFallback(
          mkPath as string,
          chapterNumber,
          series?.slug ?? '',
          series?.altTitles ? [series.title, ...series.altTitles] : [series?.title ?? ''],
        )
    load
      .then((urls) => {
        if (!cancelled) setPageImages(urls)
      })
      .catch(() => {
        if (!cancelled) setPageImages([])
      })
      .finally(() => {
        if (!cancelled) setImagesLoading(false)
      })
    return () => {
      cancelled = true
    }
    // series slug/title feed the mgeko fallback resolution; chapterNumber
    // keys the lookup
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [chapter?.mdChapterId, chapter?.chapterPath, chapterNumber, series?.slug])

  // Track reading progress + scroll position
  useEffect(() => {
    if (!series || !chapter) return
    setProgress({
      seriesId: series.id,
      chapterId: chapter.id,
      chapterNumber: chapter.number,
      updatedAt: Date.now(),
    })
  }, [series, chapter, setProgress])

  // Chapter-specific document title/meta. The SSR chapter document already
  // has them (functions/read), but client-side chapter navigation never
  // reloads the document — without this the title stays on the series page
  // and browser history/bookmarks record the series, not the chapter. Same
  // format as the SSR renderer so both agree.
  useEffect(() => {
    if (!series || !chapter) return
    setSeo(
      buildChapterMeta({
        title: series.title,
        slug: titleSlug(series),
        kind: series.kind === 'manhua' ? 'manhua' : 'manhwa',
        chapter: chapter.number,
        total: chapterSource.length,
        date: chapter.releaseDate ? String(chapter.releaseDate).slice(0, 10) : undefined,
        genres: series.genres,
        coverUrl: series.coverCdn || series.coverUrl,
        author: series.author,
      }),
    )
  }, [series, chapter, chapterSource.length])

  useEffect(() => {
    const onScroll = () => {
      const doc = document.documentElement
      const max = doc.scrollHeight - doc.clientHeight
      setScrollPct(max > 0 ? clamp((window.scrollY / max) * 100, 0, 100) : 0)
    }
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  // Scroll to top when chapter changes
  useEffect(() => {
    window.scrollTo({ top: 0 })
  }, [slug, chapterNumber])

  const goChapter = useCallback(
    (num: number) => {
      if (!series) return
      if (num < 1 || num > chapterSource.length) return
      if (isPostHogEnabled) {
        posthog.capture('chapter_navigated', {
          series_id: series.id,
          from_chapter_number: chapterNumber,
          to_chapter_number: num,
        })
      }
      navigate(chapterHref(series, num))
    },
    [series, chapterNumber, chapterSource.length],
  )

  // Keyboard navigation
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = document.activeElement
      if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) return
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { if (next) goChapter(next.number) }
      if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { if (prev) goChapter(prev.number) }
      if (e.key === 'Escape') {
        if (settingsOpen) setSettingsOpen(false)
        else if (series) navigate(`${seriesHref(series)}`)
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [goChapter, chapterNumber, settingsOpen, series])

  const toggleFullscreen = async () => {
    try {
      if (!document.fullscreenElement) {
        await document.documentElement.requestFullscreen()
        setFullscreen(true)
      } else {
        await document.exitFullscreen()
        setFullscreen(false)
      }
    } catch {
      /* fullscreen unavailable */
    }
  }

  // mk series from the compact mobile snapshot hydrate their full chapter
  // list (with page paths) via useRealChapters — keep the skeleton up until
  // that lands, otherwise the chapter resolves without a readable source.
  // Skeleton mirrors the real layout (header card + page shapes) instead of
  // a bare centered spinner: the spinner state shifted the whole page when
  // content replaced it — a top-CLS offender in field data (0.538).
  if (loading || (series?.isReal && realLoading && (chapterSource.length === 0 || series.chaptersPartial))) {
    return (
      <main className="min-h-screen bg-[#EFECE4]">
        <div className="mx-auto max-w-[760px] px-4 py-8">
          <div className="mb-6 rounded-[16px] border border-[#E2DED2] bg-[#F7F6F2] p-6">
            <div className="h-3 w-28 animate-pulse rounded bg-[#D3CEC0]" />
            <div className="mt-3 h-8 w-56 animate-pulse rounded bg-[#D3CEC0]" />
            <div className="mt-4 h-3 w-40 animate-pulse rounded bg-[#E5E1D6]" />
          </div>
          <div className="overflow-hidden rounded-[16px] shadow-xl ring-1 ring-black/10 bg-white">
            {Array.from({ length: 5 }).map((_, i) => (
              <div
                key={i}
                className="w-full animate-pulse bg-[#EFECE4]"
                style={{ height: 420 + (i % 3) * 60 }}
              />
            ))}
          </div>
          <div className="mt-6 flex flex-col items-center gap-3 pb-10">
            <div className="h-8 w-8 animate-spin rounded-full border-2 border-[#D3CEC0] border-t-[#D95743]" />
            <div className="text-sm font-semibold text-[#8A877D]">Loading chapter…</div>
          </div>
        </div>
      </main>
    )
  }

  if (!series || !chapter) {
    return (
      <main className="mx-auto max-w-[1240px] px-4 py-24 text-center sm:px-6 lg:px-8">
        <h1 className="text-2xl font-extrabold">Chapter Not Found</h1>
        <p className="mt-2 text-ink-soft">This chapter may have been archived or is not yet released.</p>
        <div className="mt-6">
          <Button onClick={() => navigate(series ? `${seriesHref(series)}` : '/catalog')}>
            {series ? 'Back to Series' : 'Back to Home'}
          </Button>
        </div>
      </main>
    )
  }

  const dark = prefs.atmosphere === 'dark'
  const widthCls = WIDTHS.find((w) => w.key === prefs.width)?.cls ?? 'max-w-[760px]'
  // prev/next are POSITIONAL in reading order — chapter numbers are source
  // numbers now (gaps, 0, 5.5), so number±1 is wrong. Deliberately NOT a
  // useMemo: this sits after the early returns, and a hook here changes the
  // hook count between renders (React error #310 — the blank-reader bug).
  // Sorting ≤700 chapters per render is trivial.
  const sortedChapters = [...chapterSource].sort((a, b) => a.number - b.number)
  const currentIdx = sortedChapters.findIndex((c) => c.number === chapterNumber)
  const prev = currentIdx > 0 ? sortedChapters[currentIdx - 1] : undefined
  const next =
    currentIdx >= 0 && currentIdx < sortedChapters.length - 1
      ? sortedChapters[currentIdx + 1]
      : undefined
  const myRating = ratings[chapter.id]
  const saved = inLibrary(series.id)
  const hasRealPages = !!(chapter.mdChapterId || chapter.chapterPath) && pageImages.length > 0

  return (
    <main
      className={cx(
        'min-h-screen transition-colors duration-300',
        dark ? 'bg-onyx text-paper' : 'bg-[#EFECE4] text-[#181817]',
      )}
      // native UI (select popups, scrollbars, form controls) must match the
      // READER atmosphere, not the site theme — html.dark's color-scheme
      // would render light-reader controls dark and vice versa
      style={{ colorScheme: dark ? 'dark' : 'light' }}
    >
      {/* Reading progress bar */}
      <div className="fixed inset-x-0 top-0 z-[60] h-[3px] bg-transparent">
        <div className="h-full bg-accent transition-[width] duration-150" style={{ width: `${scrollPct}%` }} />
      </div>

      {/* Reader toolbar */}
      <header
        className={cx(
          'sticky top-0 z-50 border-b backdrop-blur-md transition-colors',
          dark ? 'border-onyx-line bg-onyx/85 text-paper' : 'border-[#E2DED2] bg-[#F7F6F2]/85 text-[#181817]',
        )}
      >
        <div className="mx-auto flex h-14 max-w-[1240px] items-center gap-3 px-4 sm:px-6">
          <button
            onClick={() => navigate(`${seriesHref(series)}`)}
            className="inline-flex items-center gap-1.5 text-sm font-semibold opacity-70 transition-opacity hover:opacity-100"
            title="Return to series overview"
          >
            <ArrowLeft width={16} height={16} />
            <span className="hidden sm:inline">{series.title}</span>
            <span className="sm:hidden">Back</span>
          </button>

          <div className="flex-1" />

          {/* Chapter selector — jump to any chapter. Native <select>: instant
              with 600+ options and the OS picker on mobile. Same source of
              truth as the reader title (chapter.number). color-scheme is
              pinned to the READER atmosphere (not the site theme) so the
              native popup matches the toolbar — otherwise a dark reader over
              a light site theme renders a white popup under white text
              (invisible options), and vice versa. Options also carry explicit
              colors for browsers that don't style popups from color-scheme. */}
          {sortedChapters.length > 0 && (
            <select
              value={String(chapterNumber)}
              onChange={(e) => {
                const n = Number(e.target.value)
                if (Number.isFinite(n)) goChapter(n)
              }}
              aria-label="Select chapter"
              title="Jump to chapter"
              style={{ colorScheme: dark ? 'dark' : 'light' }}
              className={cx(
                'max-w-[10rem] cursor-pointer truncate rounded-full border border-current/20 bg-transparent px-3 py-1.5 text-xs font-bold outline-none transition-colors hover:border-current/40 focus:border-accent',
                dark ? 'text-paper' : 'text-[#181817]',
              )}
            >
              {[...sortedChapters].reverse().map((c) => (
                <option
                  key={c.id}
                  value={String(c.number)}
                  style={{ backgroundColor: dark ? '#161615' : '#ffffff', color: dark ? '#f0efeb' : '#181817' }}
                >
                  Chapter {c.number}
                </option>
              ))}
            </select>
          )}

          <span className="hidden rounded-full px-2 py-1 text-xs font-bold uppercase tracking-wide opacity-60 sm:block">
            {pageImages.length || chapter.pageCount} pages
          </span>

          <button
            onClick={() => prev && goChapter(prev.number)}
            disabled={!prev}
            className="grid h-9 w-9 place-items-center rounded-full border border-current/20 opacity-70 transition-all hover:opacity-100 disabled:opacity-25"
            aria-label="Previous Chapter"
            title="Previous chapter (←)"
          >
            <ChevronLeft width={17} height={17} />
          </button>
          <button
            onClick={() => next && goChapter(next.number)}
            disabled={!next}
            className="grid h-9 w-9 place-items-center rounded-full border border-current/20 opacity-70 transition-all hover:opacity-100 disabled:opacity-25"
            aria-label="Next Chapter"
            title="Next chapter (→)"
          >
            <ChevronRight width={17} height={17} />
          </button>

          <button
            onClick={() => setAtmosphere(dark ? 'light' : 'dark')}
            className="grid h-9 w-9 place-items-center rounded-full border border-current/20 opacity-70 transition-all hover:opacity-100"
            title={dark ? 'Reader atmosphere set to Editorial Light' : 'Reader atmosphere set to Onyx Dark'}
          >
            {dark ? <Sun width={16} height={16} /> : <Moon width={16} height={16} />}
          </button>

          <button
            onClick={toggleFullscreen}
            className="hidden h-9 w-9 place-items-center rounded-full border border-current/20 opacity-70 transition-all hover:opacity-100 sm:grid"
            title={fullscreen ? 'Exit Fullscreen' : 'Fullscreen'}
          >
            {fullscreen ? <Minimize2 width={15} height={15} /> : <Maximize2 width={15} height={15} />}
          </button>

          <button
            onClick={() => setSettingsOpen(true)}
            className="grid h-9 w-9 place-items-center rounded-full border border-current/20 opacity-70 transition-all hover:opacity-100"
            title="Reader Settings"
          >
            <Settings2 width={16} height={16} />
          </button>
        </div>
      </header>

      {/* Canvas */}
      <div ref={topRef} className="mx-auto px-0 py-8 sm:px-4">
        <div className={cx('mx-auto', widthCls)}>
          {/* Chapter header card */}
          <div
            className={cx(
              'mb-6 rounded-[16px] border p-6',
              dark ? 'border-onyx-line bg-onyx-2' : 'border-[#E2DED2] bg-[#F7F6F2]',
            )}
          >
            <div className="eyebrow text-accent">{series.title}</div>
            <h1 className="mt-2 text-2xl font-extrabold tracking-tight sm:text-3xl">
              Chapter {chapter.number}
            </h1>
            <div className={cx('mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs', dark ? 'text-white/50' : 'text-ink-faint')}>
              <span>Released {formatDate(chapter.releaseDate)}</span>
              <span>{series.genres.join(' · ')}</span>
            </div>
          </div>

          {/* Chapter pages — real pages (MangaDex / MangaKatana) when
              available, stylized previews otherwise */}
          <div className="overflow-hidden rounded-[16px] shadow-xl ring-1 ring-black/10">
            {chapter.mdChapterId || chapter.chapterPath ? (
              imagesLoading ? (
                // Page skeletons while the real images stream in
                <div className={cx('flex flex-col gap-2 p-3', dark ? 'bg-onyx-2' : 'bg-white')}>
                  {Array.from({ length: Math.max(3, Math.min(chapter.pageCount, 12)) }).map((_, i) => (
                    <div
                      key={i}
                      className={cx(
                        'w-full animate-pulse rounded-lg',
                        dark ? 'bg-white/8' : 'bg-[#EFECE4]',
                      )}
                      style={{ height: 420 + (i % 3) * 60 }}
                    />
                  ))}
                </div>
              ) : hasRealPages ? (
                <div className={cx('reader-pages flex flex-col', dark ? 'bg-onyx-2' : 'bg-white')}>
                  {pageImages.map((url, i) => (
                    <img
                      key={i}
                      src={url}
                      alt={`Page ${i + 1}`}
                      // The first page is the chapter's LCP element — load it
                      // eagerly at the highest fetch priority; everything
                      // below scrolls in lazily. Async decoding keeps
                      // long-strip scrolling smooth on phones. (fetchpriority,
                      // lowercase, is the React 18 spelling of the attribute.)
                      loading={i === 0 ? 'eager' : 'lazy'}
                      {...(i === 0 ? ({ fetchpriority: 'high' } as never) : {})}
                      decoding="async"
                      className="block w-full select-none"
                      draggable={false}
                      // Page images load DIRECT from the source CDN (saves a
                      // Function invocation per page against the daily
                      // budget). If a direct load fails — hotlink block,
                      // expired token URL, dead CDN node — swap to the
                      // same-origin proxy once; the marker prevents a loop.
                      onError={(e) => {
                        const el = e.currentTarget
                        if (el.dataset.proxied) return
                        const proxied = proxyImageUrl(el.src)
                        if (proxied && proxied !== el.src) {
                          el.dataset.proxied = '1'
                          el.src = proxied
                        }
                      }}
                    />
                  ))}
                </div>
              ) : (
                // Source has no pages for this chapter (e.g. not uploaded
                // upstream yet) — say so instead of showing placeholder art
                <div
                  className={cx(
                    'flex flex-col items-center gap-3 px-6 py-16 text-center',
                    dark ? 'bg-onyx-2 text-white/70' : 'bg-white text-ink-soft',
                  )}
                >
                  <ImageOff width={28} height={28} className="text-accent" />
                  <p className="text-sm font-bold text-current">
                    This chapter's pages aren't available from the source yet.
                  </p>
                  <p className="max-w-sm text-xs">
                    The chapter exists but its images haven't been published
                    upstream — check back later or read another chapter.
                  </p>
                  <div className="mt-2 flex flex-wrap justify-center gap-2">
                    {prev && (
                      <button
                        type="button"
                        onClick={() => prev && goChapter(prev.number)}
                        className={cx(
                          'rounded-full px-4 py-2 text-xs font-bold',
                          dark ? 'bg-white/10 text-white hover:bg-white/20' : 'bg-ink/5 hover:bg-ink/10',
                        )}
                      >
                        ← Chapter {prev.number}
                      </button>
                    )}
                    <button
                      type="button"
                      onClick={() => navigate(`${seriesHref(series)}`)}
                      className={cx(
                        'rounded-full px-4 py-2 text-xs font-bold',
                        dark ? 'bg-white/10 text-white hover:bg-white/20' : 'bg-ink/5 hover:bg-ink/10',
                      )}
                    >
                      All chapters
                    </button>
                    {next && (
                      <button
                        type="button"
                        onClick={() => next && goChapter(next.number)}
                        className={cx(
                          'rounded-full px-4 py-2 text-xs font-bold',
                          dark ? 'bg-white/10 text-white hover:bg-white/20' : 'bg-ink/5 hover:bg-ink/10',
                        )}
                      >
                        Chapter {next.number} →
                      </button>
                    )}
                  </div>
                </div>
              )
            ) : (
              Array.from({ length: chapter.pageCount }).map((_, i) => (
                <ReaderPage
                  key={i}
                  index={i}
                  total={chapter.pageCount}
                  seed={`${series.slug}-${chapter.number}-${i}`}
                  hue={series.hue}
                  accentHue={series.accentHue}
                  dark={dark}
                />
              ))
            )}
          </div>

          {/* End-of-chapter thanks card — shown once, after the final page */}
          <img
            src="/chapter-end.jpg"
            alt="Thanks for reading on manhwas.site"
            loading="lazy"
            className="mt-6 block w-full select-none rounded-[16px] shadow-xl ring-1 ring-black/10"
            draggable={false}
          />

          {/* End-of-chapter card */}
          <div
            className={cx(
              'mt-6 rounded-[16px] border p-6 text-center',
              dark ? 'border-onyx-line bg-onyx-2' : 'border-[#E2DED2] bg-[#F7F6F2]',
            )}
          >
            <div className="eyebrow text-ink-faint">End of Chapter {chapter.number}</div>
            <h3 className="mt-2 text-xl font-extrabold tracking-tight">Rate this chapter</h3>
            <div className="mt-3 flex justify-center">
              <StarRating
                value={myRating ?? 0}
                size={26}
                onRate={(v) => rateChapter(chapter.id, v)}
              />
            </div>
            {myRating && (
              <p className="mt-2 text-xs font-medium text-accent">Rating recorded. Thank you!</p>
            )}

            <div className="mt-6 flex flex-wrap justify-center gap-3">
              <ReaderBtn dark={dark} onClick={() => navigate('/')}>
                <HomeIcon width={16} height={16} /> Home
              </ReaderBtn>
              {prev ? (
                <ReaderBtn dark={dark} onClick={() => goChapter(prev.number)}>
                  <ChevronLeft width={16} height={16} /> Previous Chapter
                </ReaderBtn>
              ) : (
                <ReaderBtn dark={dark} onClick={() => navigate(`${seriesHref(series)}`)}>
                  Back to Series
                </ReaderBtn>
              )}
              {next ? (
                <ReaderBtn dark={dark} accent onClick={() => goChapter(next.number)}>
                  Next Chapter <ChevronRight width={16} height={16} />
                </ReaderBtn>
              ) : (
                <ReaderBtn dark={dark} accent onClick={() => navigate(`${seriesHref(series)}`)}>
                  You're caught up — Back to Series
                </ReaderBtn>
              )}
            </div>

            {!next && (
              <p className={cx('mt-4 text-xs', dark ? 'text-white/50' : 'text-ink-faint')}>
                You are currently caught up to the latest release. New chapters drop every{' '}
                {series.schedule}.
              </p>
            )}
          </div>

          {/* 300x250 banner after the chapter (approved zone) */}
          <div className="mt-6 flex justify-center">
            <BannerAd size="300x250" />
          </div>

          {/* Chapter comments — read by everyone, posting needs an account */}
          <div className="mt-6">
            <Comments
              type="chapter"
              threadKey={`${slug.toLowerCase().replace(/[^a-z0-9-]/g, '-')}-c${chapterNumber}`}
              dark={dark}
              heading={`Comments — Chapter ${chapterNumber}`}
            />
          </div>
        </div>
      </div>

      {/* Scroll-to-top */}
      {scrollPct > 8 && (
        <button
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          aria-label="Scroll to top"
          title="Scroll to top"
          className={cx(
            'fixed bottom-6 right-6 z-[60] grid h-11 w-11 place-items-center rounded-full border shadow-lg transition-all hover:scale-105 active:scale-95',
            dark
              ? 'border-white/25 bg-onyx-2 text-white hover:border-white'
              : 'border-[#181817]/20 bg-[#F7F6F2] text-[#181817] hover:border-[#181817]',
          )}
        >
          <ArrowUp width={18} height={18} />
        </button>
      )}

      {/* Settings drawer */}
      {settingsOpen && (
        <div className="fixed inset-0 z-[70] flex justify-end">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={() => setSettingsOpen(false)} />
          <div
            className={cx(
              'relative h-full w-[340px] max-w-[90vw] overflow-y-auto border-l p-6 shadow-2xl',
              dark ? 'border-onyx-line bg-onyx-2 text-paper' : 'border-[#E2DED2] bg-[#F7F6F2] text-[#181817]',
            )}
          >
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-extrabold tracking-tight">Reader Settings</h3>
              <button onClick={() => setSettingsOpen(false)} aria-label="Close" className="opacity-60 hover:opacity-100">
                <X width={18} height={18} />
              </button>
            </div>

            <div className="mt-7">
              <div className="eyebrow mb-3 text-ink-faint">Reader Color Atmosphere</div>
              <div className="grid grid-cols-2 gap-2">
                <SettingTile
                  active={!dark}
                  onClick={() => setAtmosphere('light')}
                  icon={<Sun width={16} height={16} />}
                  label="Editorial Light"
                  dark={dark}
                />
                <SettingTile
                  active={dark}
                  onClick={() => setAtmosphere('dark')}
                  icon={<Moon width={16} height={16} />}
                  label="Onyx Dark"
                  dark={dark}
                />
              </div>
            </div>

            <div className="mt-7">
              <div className="eyebrow mb-3 text-ink-faint">Default Reader Width</div>
              <div className="grid grid-cols-2 gap-2">
                        {WIDTHS.map((w) => (
                  <SettingTile
                    key={w.key}
                    active={prefs.width === w.key}
                    onClick={() => setWidth(w.key)}
                    icon={<AlignCenterHorizontal width={16} height={16} />}
                    label={w.label}
                    dark={dark}
                  />
                ))}
              </div>
            </div>

            <div className="mt-7">
              <div className="eyebrow mb-3 text-ink-faint">Chapter Navigation</div>
              <div className="space-y-2 text-xs">
                {[
                  ['Next chapter', '→ or ↓'],
                  ['Previous chapter', '← or ↑'],
                  ['Close reader / settings', 'Esc'],
                ].map(([action, key]) => (
                  <div key={action} className="flex items-center justify-between">
                    <span className="opacity-70">{action}</span>
                    <kbd className={cx('rounded border px-2 py-0.5 font-semibold', dark ? 'border-onyx-line' : 'border-[#D3CEC0]')}>
                      {key}
                    </kbd>
                  </div>
                ))}
              </div>
            </div>

            <div className="mt-7">
              <button
                onClick={() => toggleLibrary(series.id, series.title)}
                className={cx(
                  'flex w-full items-center justify-center gap-2 rounded-full py-3 text-sm font-semibold transition-colors',
                  saved
                    ? 'bg-accent text-white'
                    : dark
                      ? 'bg-white/10 text-white hover:bg-white/20'
                      : 'bg-[#181817] text-[#F7F6F2] hover:bg-accent hover:text-white',
                )}
              >
                <Bookmark width={15} height={15} />
                {saved ? 'Saved to Library' : 'Save to Library'}
              </button>
              <p className={cx('mt-3 text-center text-xs', dark ? 'text-white/50' : 'text-ink-faint')}>
                Notify when bookmarked series drop new weekly chapters
              </p>
            </div>

            <div className={cx('mt-7 rounded-[14px] border p-4 text-xs', dark ? 'border-onyx-line text-white/60' : 'border-[#E2DED2] text-[#8A877D]')}>
              <div className="font-bold uppercase tracking-wide">Now Reading</div>
              <div className="mt-1.5 text-sm font-semibold text-current">
                {series.title} — Ch. {chapter.number}
              </div>
              <div className="mt-0.5">
                ★ {series.rating.toFixed(1)} · {formatViews(series.views)} views · {series.status}
              </div>
            </div>
          </div>
        </div>
      )}
    </main>
  )
}

/* Reader-scoped button with pinned palette — the reader canvas keeps its own
 * atmosphere independent of the global site theme. */
function ReaderBtn({
  dark, accent, onClick, children,
}: {
  dark: boolean
  accent?: boolean
  onClick: () => void
  children: React.ReactNode
}) {
  return (
    <button
      onClick={onClick}
      className={cx(
        'inline-flex h-11 items-center justify-center gap-2 rounded-full px-5 text-sm font-semibold transition-all duration-200 active:scale-[0.98]',
        accent
          ? 'bg-accent text-white hover:bg-accent-dark'
          : dark
            ? 'border border-white/25 text-white hover:border-white hover:bg-white hover:text-[#181817]'
            : 'border border-[#181817]/25 text-[#181817] hover:border-[#181817] hover:bg-[#181817] hover:text-white',
      )}
    >
      {children}
    </button>
  )
}

function SettingTile({
  active, onClick, icon, label, dark,
}: {
  active: boolean
  onClick: () => void
  icon: React.ReactNode
  label: string
  dark: boolean
}) {
  return (
    <button
      onClick={onClick}
      className={cx(
        'flex items-center gap-2 rounded-[12px] border px-3 py-2.5 text-sm font-semibold transition-all',
        active
          ? 'border-accent bg-accent text-white'
          : dark
            ? 'border-onyx-line text-white/70 hover:border-white/40'
            : 'border-[#D3CEC0] text-[#55534C] hover:border-[#181817]',
      )}
    >
      {icon}
      {label}
    </button>
  )
}

/* ------------------------------------------------------------------ *
 * Procedural reader page — a stylized webtoon panel layout.           *
 * Deterministic per (series, chapter, page).                          *
 * ------------------------------------------------------------------ */
function ReaderPage({
  index, total, seed, hue, accentHue, dark,
}: {
  index: number
  total: number
  seed: string
  hue: number
  accentHue: number
  dark: boolean
}) {
  const panels = useMemo(() => {
    const rand = seededRandom(seed)
    const count = 2 + Math.floor(rand() * 3) // 2-4 panels
    return Array.from({ length: count }).map((_, i) => ({
      height: 180 + Math.floor(rand() * 220),
      tone: rand(),
      kind: rand(),
    }))
  }, [seed])

  return (
    <div
      className={cx('relative', dark ? 'bg-onyx-2' : 'bg-white')}
      style={{ aspectRatio: undefined }}
    >
      <div className="flex flex-col gap-3 p-3 sm:gap-4 sm:p-5">
        {panels.map((p, i) => (
          <div
            key={i}
            className="relative w-full overflow-hidden rounded-lg"
            style={{
              height: p.height,
              background: `linear-gradient(${140 + p.tone * 80}deg,
                hsl(${hue} ${28 + p.tone * 20}% ${dark ? 14 + p.tone * 10 : 86 - p.tone * 14}%) 0%,
                hsl(${accentHue} ${24 + p.tone * 26}% ${dark ? 20 + p.tone * 12 : 78 - p.tone * 16}%) 100%)`,
            }}
          >
            {/* Panel art motifs */}
            <svg className="absolute inset-0 h-full w-full opacity-60" viewBox="0 0 400 200" preserveAspectRatio="xMidYMid slice">
              {p.kind < 0.33 && (
                <>
                  <circle cx={80 + p.tone * 240} cy="100" r="56" fill="rgba(255,255,255,0.10)" />
                  <circle cx={80 + p.tone * 240} cy="100" r="88" fill="none" stroke="rgba(255,255,255,0.14)" strokeWidth="1.5" />
                </>
              )}
              {p.kind >= 0.33 && p.kind < 0.66 && (
                <path
                  d={`M0 ${160 - p.tone * 40} L${90 + p.tone * 60} ${60 + p.tone * 50} L${200 + p.tone * 80} ${120 - p.tone * 30} L400 ${70 + p.tone * 60} L400 200 L0 200 Z`}
                  fill="rgba(0,0,0,0.18)"
                />
              )}
              {p.kind >= 0.66 && (
                <>
                  <line x1="0" y1={40 + p.tone * 120} x2="400" y2={20 + p.tone * 100} stroke="rgba(255,255,255,0.2)" strokeWidth="1.5" />
                  <line x1="0" y1={90 + p.tone * 90} x2="400" y2={70 + p.tone * 110} stroke="rgba(255,255,255,0.12)" strokeWidth="1" />
                  <circle cx={300 + p.tone * 60} cy={50 + p.tone * 80} r="30" fill="rgba(255,255,255,0.08)" />
                </>
              )}
            </svg>
            {/* Vignette */}
            <div className="absolute inset-0" style={{ background: 'radial-gradient(110% 110% at 50% 30%, transparent 60%, rgba(0,0,0,0.22) 100%)' }} />
          </div>
        ))}
      </div>

      {/* Page number footer */}
      <div
        className={cx(
          'flex items-center justify-between px-4 pb-3 text-[10px] font-semibold uppercase tracking-[0.2em] sm:px-6',
          dark ? 'text-white/35' : 'text-[#8A877D]',
        )}
      >
        <span>MANHWAS</span>
        <span>
          {index + 1} / {total}
        </span>
      </div>
    </div>
  )
}
